"""Test that the integers are checked against the safe integer range."""


# This code has been automatically generated by aas-core-codegen.
# Do NOT edit or append.


import unittest


import dummy.common as our_common


class TestPredicateAndMessages(unittest.TestCase):
    def test_is_safe_integer(self) -> None:
        for value in [0, 2 ** 53 - 1, -(2 ** 53 - 1)]:
            self.assertTrue(our_common.is_safe_integer(value), f"for {value}")

        for value in [2 ** 53, -(2 ** 53), 10 ** 400]:
            self.assertFalse(our_common.is_safe_integer(value), f"for {value}")

    def test_unsafe_json_able_integer_message(self) -> None:
        self.assertEqual(
            "Expected a JSON-able value, but got the integer -9007199254740992, "
            "which is outside the safe integer range [-2^53 + 1, 2^53 - 1]",
            our_common.unsafe_json_able_integer_message(-(2 ** 53))
        )


if __name__ == "__main__":
    unittest.main()


